def compute(case,mode,out):
 import p14h.model as M
 from p14h.causal_observer import Observer as Source
 out=Path(out);out.mkdir();target=next((B/'runs').glob(f'p14h-{case}-*'));info=json.load(open(target/('information-v2.json' if (target/'information-v2.json').exists() else 'information.json')));analysis=R/info['source_analysis'] if info.get('source_analysis') else target/'analysis-v1';obs=load(target/'run',analysis);d=json.load(open(B/f'cadence-recovery-v2/{case}/input.json'));i=d['initial'];side=json.load(open(target/'plan.json'))['side'];d=planned_cell(d,side);core,_=read(target/'run/gz-motor/observer-core.bin',CORE,b'P14RCORE',True);post=core[core['kind']==2];mapping={}
 for j,sample in enumerate(obs['sample_us']):
  z=int(np.searchsorted(post['wall_ns'],obs['run_wall_ns'][j],side='right')-1)
  if z>=0:mapping[int(sample)]=(int(post['sample_us'][z]),int(obs['lp_sample'][j]),int(obs['att_sample'][j]))
 collected=[];failure=[]
 class TracedCtl(M.Ctl):
  def step(self,*args,**kwargs):
   value=super().step(*args,**kwargs);action,info=value
   if 'input' in info:collected.append(dict(sample=int(args[1]),action=np.array(action).copy(),h=self.h.copy(),input=np.array(info['input']).copy()))
   return value
 M.Ctl=TracedCtl
 class Replaced(Source):
  def __init__(self,*a,**k):
   super().__init__(*a,**k);self.payloads={('LP',self.lp_sample):np.r_[self.p,self.v].copy(),('att',self.att_sample):self.q.copy()}
   for _,kind,v,s in self.queue:self.payloads[kind,s]=v.copy()
  def publish(self,control,fused):
   super().publish(control,fused)
   for _,kind,v,s in self.queue:self.payloads[kind,s]=v.copy()
  def step(self,control,*args):
   if control not in mapping:
    failure.append(dict(kind='EXHAUSTED_DIAGNOSTIC_WORD',control_sample=int(control)));raise ValueError('diagnostic word exhausted')
   target,lp,att=mapping[control]
   if target>control:
    failure.append(dict(kind='OP_COMPLETED_SAMPLE_AHEAD_OF_CONTROL_SAMPLE',control_sample=int(control),OP_completed_sample=int(target),lead_us=int(target-control),need='asynchronous physical/controller event queue; cannot read uncomputed physical state'));raise ValueError('source word leads single-grid nominal physical state')
   self.lag=int(control-target);value=super().step(control,*args)
   if mode=='producer+cache-timestamps':
    if ('LP',lp) not in self.payloads or ('att',att) not in self.payloads:
     failure.append(dict(kind='CACHE_SAMPLE_WITHOUT_MODEL_PRODUCED_PAYLOAD',control_sample=int(control),OP_completed_sample=int(target),required_LP=int(lp),required_attitude=int(att),LP_present=('LP',lp) in self.payloads,att_present=('att',att) in self.payloads,need='future fused-correction/producer mode not generated by nominal payload model'));raise ValueError('actual timestamp has no corresponding model-produced payload')
    self.p=self.payloads['LP',lp][:3].copy();self.v=self.payloads['LP',lp][3:].copy();self.q=self.payloads['att',att].copy();self.lp_sample=lp;self.att_sample=att;value=self.p.copy(),self.v.copy(),self.q.copy(),self.gyro.copy()
   return value
 M.Observer=Replaced;tmp=out/'inputs';tmp.mkdir();shutil.copyfile(R/'data/p14r-20261027/offline-build-v2/libop.bin',tmp/'libop.bin');shutil.copyfile(B/'cadence-recovery-v2/cadence.bin',tmp/'cadence.bin');end=i['profile_s']+.004*(((int(obs['sample_us'][-1])-i['sample_us'])//4000)-.25)
 try:r=M.forecast(d,{},dict(np.load(R/'data/p13-20261026-freeze/models/policy.npz')),limit=end,observer_library=tmp/'libop.bin')
 except Exception as e:
  lookup={int(t):j for j,t in enumerate(obs['sample_us'])};rows=[x for x in collected if x['sample'] in lookup];ix=np.array([lookup[x['sample']] for x in rows]);t=obs['t'][ix];err={key:np.linalg.norm(np.array([x[key] for x in rows])-obs[{'input':'input','action':'action','h':'h_after'}[key]][ix],axis=1) for key in ['input','action','h']} if rows else {};np.savez_compressed(out/'valid-diagnostic-prefix.npz',sample=np.array([x['sample'] for x in rows]),**{key:np.array([x[key] for x in rows]) for key in ['input','action','h']});write(out/'result.json',dict(case=case,mode=mode,status='DIAGNOSTIC_UNCLOSED',failure=failure or [dict(kind='OTHER_RUNTIME_ERROR',error=repr(e))],error=repr(e),valid_prefix_rows=len(rows),valid_prefix_end_profile_s=float(t[-1]) if len(t) else None,prefix_RMSE={key:float(np.sqrt(np.mean(v*v))) for key,v in err.items()},future_timestamps_only=True,not_in_autonomous_scores=True));print('DIAGNOSTIC_UNCLOSED',case,mode,failure);return
 np.savez_compressed(out/'trace.npz',**{k:v for k,v in r.items() if isinstance(v,np.ndarray)});tr=r['trace'];ix=np.flatnonzero((obs['sample_us']>i['sample_us'])&(obs['sample_us']<=i['sample_us']+4000*(len(tr)-1)));k=((obs['sample_us'][ix]-i['sample_us'])//4000).astype(int);b=d['plan']['windows_profile_s'][0][1];errs={'input':np.linalg.norm(r['inputs'][k]-obs['input'][ix],axis=1),'action':np.linalg.norm(tr[k,8:12]-obs['action'][ix],axis=1),'h':np.linalg.norm(tr[k,12:28]-obs['h_after'][ix],axis=1),'LP':np.linalg.norm(tr[k,42:45]-obs['position'][ix],axis=1),'attitude_deg':angle(tr[k,48:52],obs['attitude'][ix])};t=obs['t'][ix];windows=[]
 for width in [.064,.5,2.]:
  mask=(t>=b)&(t<=b+width);windows.append(dict(window=width,complete=bool(t[-1]>=b+width-.004),RMSE={key:float(np.sqrt(np.mean(v[mask]**2))) if np.any(mask) else None for key,v in errs.items()}))
 write(out/'result.json',dict(case=case,mode=mode,status='DIAGNOSTIC_COMPLETED_OBSERVED_PREFIX',stop=r['stop'],source_inputs='actual future OP-completion sample and optional actual consumed cache timestamps, NO future payloads; diagnostic ONLY',windows=windows,full_prefix_RMSE={key:float(np.sqrt(np.mean(v*v))) for key,v in errs.items()},first_errors={key:first(t,e,dict(input=.05,action=.02,h=.1,LP=.1,attitude_deg=2.5)[key]) for key,e in errs.items()},not_in_autonomous_scores=True));print('TIMESTAMP_REPLACEMENT',case,mode)

if __name__=='__main__':
 if sys.argv[1]=='child':compute(sys.argv[2],sys.argv[3],sys.argv[4])
 else:
  out=register(sys.argv[1],'v2 same eight registered diagnostics; fix diagnostic endpoint rounding and preserve structured valid prefix on missing generated payload/phase lead. v1 errors retained; frozen model unchanged',cases=['d01','d02','d03','d04'],modes=['producer-completion','producer+cache-timestamps'],CPU_cap=240,no_model_fit=True,not_independent_validation=True)
  for case in ['d01','d02','d03','d04']:
   for j,mode in enumerate(['producer-completion','producer+cache-timestamps']):
    name=case+'-'+str(j);r=run(['/usr/bin/taskset','-c','0-3',PY,Path(__file__),'child',case,mode,out/name/'result'],out/name,cpu=30,wall=45,scope='known future timestamp diagnostic only, no new candidate');print(name,r['rc'],flush=True)
